    'running.verifying': 'Проверяем',
    'settings.announceToAgent': 'Объявлять доску задач агентам',
    'settings.announceToAgentHint': 'Включено: в системный промпт каждого агента добавляется краткое упоминание этой доски. Выключено: объявления нет, агенты узнают о доске, только когда вы о ней скажете.',
    'settings.cardDefaultModeHint': 'Пустое значение ничего не закрепляет: новая карточка следует умолчанию развёртывания. Значение выбирается так: явный выбор в диалоге новой задачи, затем значение, перенесённое с исходной карточки или родителя, затем это умолчание; подзадача сохраняет то, что уже закрепил родитель.',
    'settings.cardDefaultModelHint': 'Пустое значение — умолчание хоста (agent-default-model). Явный выбор в диалоге главнее значения, перенесённого с исходной карточки или родителя, а то главнее этого умолчания; вызывающий, закрепивший свою модель, не наследует уровень рассуждения по умолчанию.',
    'settings.cardDefaultPermissionHint': 'Пустое значение ничего не задаёт (действует умолчание сессии). Умолчание выше базового разрешения сессии остаётся лишь предзаполнением: карточке всё равно нужно подтверждение человека, прежде чем она сможет запуститься. Подзадача никогда не наследует разрешение родителя; это умолчание заполняется только там, где родитель ничего не закрепил.',
    'settings.cardDefaultsCardHint': 'То, с чем открывается диалог новой задачи: пресет агента, разрешение, модель и уровень рассуждения. Пустое значение ничего не задаёт, поэтому создание карточки ведёт себя как без настройки. Это лишь предзаполнение, оно не меняет существующих смыслов, и каждая новая карточка остаётся редактируемой; уровень рассуждения по умолчанию действует, только пока карточка остаётся на настроенной модели по умолчанию.',
    'settings.cardDefaultsTitle': 'Умолчания новой карточки',
    'settings.collapse': 'Скрыть настройки',
    'settings.description': 'Оркестрация задач, объявление агентам и приёмка цели.',
    'settings.discard': 'Отменить изменения',
    'settings.enabled': 'Включить доску задач',
    'settings.enabledCardHint': 'Общий переключатель, объявление, защита от сна и глубина подзадач.',
    'settings.enabledHint': 'Когда выключено, пункт боковой панели и вид доски скрыты, а инструменты task_board_* у агента не зарегистрированы; пока включено, любая сессия может читать доску, её подзадачи и расписания и управлять ими через эти инструменты.',
    'settings.expand': 'Показать настройки',
    'settings.goalRunGlobal': 'Глобально: запускать задачи через встроенный /goal',
    'settings.goalRunGlobalDisabledTaskOption': 'Глобальный переключатель встроенного /goal выключен: задачный флаг можно отметить или снять, но сейчас он не действует, а сохранённый выбор никогда не перезаписывается; включение глобального переключателя применит его. Это выполнение пройдёт один обычный раунд без приёмки цели.',
    'settings.goalRunGlobalHint': 'По умолчанию выключено. Пока выключено, каждая задача проходит один обычный раунд и никогда не вызывает встроенный /goal в dsh; запуск использует /goal, только если включено И отмечен задачный флаг (см. флаг задачи ниже). Задачный флажок всегда доступен, и этот переключатель его не перезаписывает: общий выключатель решает лишь, действует ли выбор. Состояние фиксируется при старте выполнения, поэтому влияет только на запуски, открытые после этого.',
    'settings.goalVerification': 'Включить приёмку задач',
    'settings.goalVerificationCardHint': 'Переключатель, модель-судья и порог критериев.',
    'settings.goalVerificationEffort': 'Уровень рассуждения',
    'settings.goalVerificationEffortFallback': 'Выбранный уровень рассуждения {requested} не поддерживается целевой моделью; используется {resolved}.',
    'settings.goalVerificationEffortFallbackNone': 'Выбранный уровень рассуждения {requested} не поддерживается целевой моделью; используется уровень по умолчанию этой модели (явно не передаётся).',
    'settings.goalVerificationEffortHint': 'Пустое значение наследует уровень хоста по умолчанию. Уровень, который целевая модель не объявляет, не передаётся вслепую: приёмка откатывается к уровню по умолчанию этой модели, и откат указывается ниже.',
