    'settingsBottomTerminalDesc': 'Когда нижняя панель впервые за сессию разворачивается, в ней пытается открыться новая вкладка терминала (лимит терминалов по-прежнему действует; включено по умолчанию)',
    'settingsBottomTerminalTitle': 'Автоматически открывать терминал при первом разворачивании нижней панели',
    'settingsBrowserLoopbackDesc': 'Список разрешённых петлевых адресов через запятую (например, localhost:5174 или 127.0.0.1:8080), которые может посещать браузер боковой панели; пустое значение по умолчанию блокирует все локальные адреса. Песочница по-прежнему действует — страницы не могут читать данные интерфейса',
    'settingsBrowserLoopbackPlaceholder': 'например, localhost:5174, 127.0.0.1:8080',
    'settingsBrowserLoopbackTitle': 'Разрешённые локальные адреса',
    'settingsBrowserSandboxDesc': 'При выключенной песочнице любой посещённый сайт работает с тем же источником, что и интерфейс: он может читать данные сессии и действовать от имени вашей сессии. Включайте только для полностью доверенных сайтов',
    'settingsBrowserSandboxTitle': 'Отключать песочницу браузера (небезопасно)',
