    'settingsCustomCssTitle': 'Свой CSS',
    'settingsDone': 'Готово',
    'settingsEditorGitGutterDesc': 'Подкрашивать колонку номеров строк редактора кода для незакоммиченных изменений и показывать при наведении авторство этой строки (автор, время и сводку коммита); в выключенном режиме все метки скрыты',
    'settingsEditorGitGutterTitle': 'Метки незакоммиченных изменений в редакторе',
    'settingsFontFamilyDesc': 'Свой шрифт терминала (стек CSS font-family вида «JetBrains Mono», monospace; оставьте пустым, чтобы использовать моноширинный шрифт темы)',
    'settingsFontFamilyPlaceholder': '«JetBrains Mono», monospace',
