    'settingsFontSizeDesc': 'Размер шрифта терминала в px (9–32, по умолчанию 13)',
    'settingsFontSizeTitle': 'Размер шрифта терминала',
    'settingsGeneralTitle': 'Общие',
    'settingsHtmlDefaultUnsafeDesc': 'Если включено, каждый новый предпросмотр HTML открывается без песочницы (тот же источник, что и у интерфейса — он может читать файлы сессии и вызывать внутренние API); в строке состояния по-прежнему есть возврат в одно нажатие',
    'settingsHtmlDefaultUnsafeTitle': 'Открывать предпросмотр HTML без песочницы по умолчанию (небезопасно)',
    'settingsHtmlSandboxDesc': 'При выключенной песочнице предпросматриваемый HTML работает с тем же источником, что и интерфейс: он может читать файлы сессии, локальное хранилище и вызывать внутренние API. Включайте только для полностью доверенных файлов',
    'settingsHtmlSandboxTitle': 'Отключать песочницу предпросмотра HTML (небезопасно)',
    'settingsIntro': 'Настройте, что показывает боковая карточка и как она себя ведёт',
    'settingsJobsDesc': 'Когда для текущего диалога появляется новая фоновая задача, страница «Задачи» создаётся в боковой карточке и помечается точкой непрочитанного (срабатывает на каждой новой задаче); боковая карточка, уже развёрнутая на другой странице, остаётся нетронутой и не переключается — нажмите на точку, чтобы перейти туда; на широких экранах боковая карточка тоже разворачивается, а узкие полноэкранные панели принудительно не открываются; выключите, чтобы не создавать её автоматически',
    'settingsJobsTitle': 'Автоматически активировать страницу «Задачи» при новой фоновой задаче',
    'settingsMobileNoAutoOpenDesc': 'На телефоне или узком экране новый субагент или фоновая задача больше не переключают на страницу «Задачи» сами (её по-прежнему можно открыть вручную)',
    'settingsMobileNoAutoOpenTitle': 'Не открывать автоматически на узких экранах',
    'settingsMobileTitle': 'Мобильный',
    'settingsMobileTreeDesc': 'На телефоне или узком экране страница «Задачи» открывается обычным деревом вместо графа workflow; переключатель внутри страницы всё равно меняет вид на лету',
    'settingsMobileTreeTitle': 'По умолчанию показывать страницу «Задачи» деревом',
    'settingsNav': 'Боковая карточка',
    'settingsOpenToolsDesc': 'Если включено, модель может сама открывать файлы, папки и страницы HTTP(S) в боковой панели через инструмент sidebar_open (по умолчанию выключено)',
    'settingsOpenToolsTitle': 'Добавлять инструмент sidebar_open для модели',
    'settingsOpenWithPluginDesc': 'По умолчанию собственные цели плагина (файловый менеджер / VS Code / Cursor / Zed / пользовательские редакторы, удалённые хосты по SSH) показываются только тогда, когда хост не сообщает о локальном связанном приложении; включите, чтобы оставить и те, и другие рядом',
    'settingsOpenWithPluginTitle': 'Всегда показывать собственные цели «Открыть с помощью» плагина',
    'settingsPopup': 'Настройки функции',
