    'settingsSaveFailed': 'Не удалось сохранить',
    'settingsShellArgsDesc': 'Явные аргументы оболочки, разделённые пробелом; если они заданы, полностью заменяют значения по умолчанию (тот же контракт, что и у yaml shellArgs)',
    'settingsShellArgsPlaceholder': 'например, -l (пусто = по умолчанию)',
    'settingsShellArgsTitle': 'Аргументы оболочки',
    'settingsShellDesc': 'Оболочка, запускаемая для терминалов интерфейса и модели (полный путь или просто имя исполняемого файла). Пустое значение оставляет прежний порядок: yaml config.shell → $SHELL / оболочка входа / Windows powershell.exe. Применяется к терминалам, открытым позже',
