    'settingsSubagentDesc': 'Когда текущий диалог порождает нового субагента, страница «Задачи» создаётся в боковой карточке и помечается точкой непрочитанного; боковая карточка, уже развёрнутая на другой странице, остаётся нетронутой и не переключается — нажмите на точку, чтобы перейти туда; на широких экранах боковая карточка тоже разворачивается, а узкие полноэкранные панели принудительно не открываются; выключите, чтобы не создавать её автоматически',
