    'conflict.hint.claude': 'claude: запускайте через bili claude (он сам выравнивает CLAUDE_CODE_AUTO_COMPACT_WINDOW) или задайте CLAUDE_CODE_AUTO_COMPACT_WINDOW равным действующему окну bili',
    'conflict.hint.codex': 'codex: bili по умолчанию перехватывает нативное сжатие (BILI_CODEX_COMPACT=intercept) — если вы задали pass, уберите переопределение, чтобы отключить; иначе сообщите версию bili',
    'conflict.hint.generic': 'отключите собственное автосжатие клиента (или направьте эту сессию в обход bili), затем начните новую сессию — реестр ведётся по сессиям, поэтому старые записи исчезнут вместе со старой сессией',
    'conflict.hint.omp': 'omp: расширение bili отменяет нативное автосжатие клиента, пока ведёт беседу — если вы это видите, вероятно, не хватает подтверждений переноса или версия устарела; сообщите клиент и версию bili',
    'conflict.hint.opencode': 'opencode: задайте в конфигурации opencode «compaction»: { «auto»: false } (или выполните bili opencode / bili plugin install opencode — они сделают это за вас)',
    'conflict.hint.pi': 'pi: расширение bili отменяет нативное автосжатие клиента, пока ведёт беседу — если вы это видите, вероятно, не хватает подтверждений переноса или версия устарела; сообщите клиент и версию bili',
    'conflict.on': 'Обнаружен конфликт сжатия',
