    'conflict.risk_active': ' найдены. Два сжимателя в одной беседе сжимают дважды и портят ссылки на сообщения, из-за чего контекст путается — оставьте ровно один сжиматель.',
    'conflict.risk_historical': ' найдены (событий за последние 7 дней нет — только штатные записи) — когда вы убедитесь, что другой сжиматель удалён или заблокирован bili, очистите их кнопкой.',
    'conflict.risk_sibling': ' найдены. Это собственные родственные расширения bili, а не сторонние сжиматели: пока сессию ведёт bili, они автоматически бездействуют (метка BILLION_CONTEXT_NATIVE в нативном режиме, иначе самопроверка baseUrl с /bili/), так что второй сжиматель не активен — проверьте, что версии свежие, и очистите эту запись; ничего удалять не нужно.',
    'conflict.risk_suspected': ' — только сигнал по имени [подозрение], а не наблюдаемое доказательство двойного сжатия. Прежде чем действовать, убедитесь, что он действительно переписывает контекст модели; плагин отображения или сворачивания вывода инструментов (например, pi-compact-transcript) не сжимает дважды и удаления не требует.',
    'conflict.risk_unconfirmed': ' — все перечисленные выше признаки НЕПОДТВЕРЖДЕНЫ: они не доказывают существование второго сжимателя (возможные причины: правки на стороне клиента, нераспознанный формат сжатия или другой плагин). Проверьте, прежде чем действовать; просмотрщик контекста только для чтения или плагин отображения и сворачивания вывода инструментов не является сжимателем и удаления не требует.',
    'conflict.what_join': ' и ',
