    'det.active_pack': 'Набор промптов',
    'det.attr_abort': '⏻ Связано с прерыванием',
    'det.attr_abort_tip': 'Промахи уложились в 30 с после прерывания клиента в середине потока — повторные попытки переписывают пересылаемый хвост; это корреляция, а не причина (метка наложения, а не отдельная категория)',
    'det.attr_client': '✎ Переписывание клиентом в середине истории',
    'det.attr_client_tip': 'Собственная пересылка истории клиента разошлась в середине списка (вставка или переписывание — другой плагин на хосте, подъём вставок, повторный рендер): пара отпечатков входящих сообщений не совпадает на этом индексе, и точная пересборка bili перенесла изменение в запрос. Пересчёт на стороне клиента, а не шов пересборки bili (#3023)',
    'det.attr_provider': '▲ Промах на стороне провайдера (аномалия)',
    'det.attr_provider_tip': 'Пришёл вскоре после предыдущего запроса, весь список сообщений которого вернулся байт в байт (целиком или его префикс с добавленными только хвостовыми сообщениями; выше предела криминалистики в 512 КиБ, что доказано устойчивой записанной головой и точным ростом числа сообщений), но апстрим не отдал свой кэш — аномалия: вытеснение или смена релей-узла. Парные случаи с большим интервалом учитываются как истечение TTL у апстрима',
    'det.attr_rest': 'остальное {x}',
    'det.attr_rest_tip': 'мелкие остатки ниже порога классификации (<8K или <30% ввода на один замер) по отдельности не классифицируются',
    'det.attr_restart': '⟳ сброс при перезапуске',
    'det.attr_restart_tip': 'После перезапуска bili или восстановления сессии окно реестра разрывается: первый запрос после перезапуска не сопоставляется с замерами до перезапуска, поэтому его промах учитывается как первый (исходный контент)',
    'det.attr_rewind': '↩ История перемотана назад',
    'det.attr_rewind_tip': 'Откат или обрезка на стороне клиента уменьшили число сообщений — это разрешённый однократный пересчёт сохранённого префикса, а не дефект',
    'det.attr_seam': '⚠ Шов кэша',
    'det.attr_seam_tip': 'Исходящие тела разошлись в середине истории без привязки к сжатию, смене модели или перезапуску — подозревается шов пересборки. Значение = токены, пересчитанные на подозрительных замерах. Если сжатие произошло за несколько минут до этого, обычно это пересчёт клиентского эха после сжатия (принадлежит сжатию начиная с #2929)',
    'det.attr_ttl': '⏱ Истечение TTL у апстрима (норма)',
